float f_n_rand(float n){
    n = fract(n * .1031);
    n *= n + 33.33;
    n *= n + n;
    return fract(n);
}
vec2 f_o_idx(vec2 o_trn, vec2 o_scl){
    //calculate an index based on a o_trn translation and o_scl scale
    float n_idx_flr = floor(o_trn.x)
        + floor(o_trn.y) * floor(o_scl.x);
    return vec2(
        n_idx_flr, 
        n_idx_flr / (floor(o_scl.x)*floor(o_scl.y))
    );
}
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float n_dscl = 1.;// dscl down scale
    vec2 o_lires = iResolution.xy * n_dscl;// lres low resolution
    vec2 o_lfc = fragCoord.xy * n_dscl;
    float n_t = iTime*0.5; 


    float n_ratio_1to_iresx = 1./ o_lires.x;

    vec2 o_lfc_nor = floor(o_lfc) / o_lires; // low frag coord normalized
    vec2 o_lfc_nor_off = (floor(o_lfc)-0.5*o_lires.xy)/ o_lires.y;
    vec2 o_fc_nor = fragCoord.xy / iResolution.xy;
    vec2 o_fc_nor_off = (fragCoord.xy-0.5*iResolution.xy) / iResolution.y;
    vec2 o_mo_nor_off = (iMouse.xy-0.5*iResolution.xy) / iResolution.y;

    if(iMouse.z == 0.){
        o_mo_nor_off = vec2(sin(n_t), cos(n_t)*0.5+0.5);
    }
    o_lfc *= (o_mo_nor_off.y)*0.3;


    vec2 o_scl_krn = vec2(5.); //krn kernel

    float n_krn_xty = o_scl_krn.x*o_scl_krn.y;
    float n_dmin = 1.;

    vec2 o_lfc_min, o_idx_min; 
    float n_rnd_min;

    float n_rnd_amp = floor(min(o_scl_krn.x, o_scl_krn.y)/2.);

    for(float n = 0.; n < n_krn_xty; n+=1.){
        float n_x = floor(mod(n, o_scl_krn.x) - floor(o_scl_krn.x/2.));
        float n_y = floor(n / o_scl_krn.x) - floor(o_scl_krn.y/2.);

        vec2 o_lfc_krn = o_lfc + vec2(n_x, n_y);
        vec2 o_idx = f_o_idx(floor(o_lfc_krn), floor(o_lires));
        float n_rand = f_n_rand(floor(o_idx.x));
        vec2 o_a = fract(o_lfc);
        vec2 o_b = vec2(n_x, n_y)+(n_rand-0.5)*n_rnd_amp;
        float n_dist = length(o_a-o_b)*.5;
        n_dist *= 1.+n_rand;
        //n_dmin = min(n_dist, n_dmin);
        if(n_dist < n_dmin){
            n_dmin = n_dist;
            o_lfc_min = o_lfc_krn;
            o_idx_min = o_idx;
            n_rnd_min = n_rand;
        }
        //n_dmin = n_dist;
    }

    fragColor = vec4(n_dmin);
    fragColor = sqrt(fragColor);

    if(o_fc_nor_off.x > o_mo_nor_off.x){
        float n_rnd1 = f_n_rand(n_rnd_min*0.3111);
        float n_rnd2 = f_n_rand(n_rnd1*0.1113);
        fragColor = vec4(n_rnd_min, n_rnd1, n_rnd2, 1.);

        fragColor *= 1.-(float(n_rnd1>0.5)*n_dmin);
    }
}
